import { RefinementList } from 'react-instantsearch';
import s from './SearchAndFilter.module.scss';

const classNames = {
  checkbox: s.checkbox,
  count: s.count,
};
export default function SearchAndFilter() {
  return (
    <aside className={s.SearchAndFilter}>
      <h3>Key</h3>
      <RefinementList
        attribute='key'
        sortBy={['name']}
        classNames={classNames}
        showMore
        limit={7}
        showMoreLimit={100}
      />
      <h3>Suffix</h3>
      <RefinementList
        attribute='suffix'
        classNames={classNames}
        showMore
        limit={8}
