import { describe, expect, it } from 'vitest';
import { render, screen } from '@testing-library/react';
import HitItem from './HitItem';

describe('<Hititem/>', () => {
  const hit = {
    key: 'C',
    suffix: 'major',
    positions: [
      {
        frets: [-1, 3, 2, 0, 1, 0],
        fingers: [0, 3, 2, 0, 1, 0],
        baseFret: 1,
        barres: [],
        midi: [48, 52, 55, 60, 64],
      },
      {
        frets: [-1, 1, 3, 3, 3, 1],
        fingers: [0, 1, 2, 3, 4, 1],
        barres: [1],
        capo: true,
        baseFret: 3,
        midi: [48, 55, 60, 64, 67],
      },
    ],
  };
  it('Should render', () => {
    const { container } = render(<HitItem hit={hit} />);
    expect(screen.getByText('Cmajor')).toBeInTheDocument();
    expect(container.querySelector('svg')).not.toBeUndefined();
    expect(screen.getByText('2 positions')).toBeInTheDocument();
  });

  it('Should render singular noun "position"', () => {
    const { positions, ...data } = hit;

    render(<HitItem hit={{ ...data, positions: [positions[0]] }} />);

    expect(screen.getByText('1 position')).toBeInTheDocument();
  });
});

.SearchAndFilter {
  position: sticky;
  top: 0;
  left: 0;
  min-width: 15vw;
  display: flex;
  flex-direction: column;
  gap: 1rem;
  padding-top: 2rem;

  height: fit-content;

  h2 {
    font-size: var(--step-0);
  }
  h3 {
    font-size: calc(var(--step-0) - 0.1vmax);
  }
  // Search box
  :global(.ais-SearchBox-form) {
    height: 32px;
    display: flex;
    align-items: center;
    position: relative;
    button {
      padding: 0 0.75rem 0 0.5rem;
      background-color: #fff0;
      border: none;
      position: absolute;
      right: 0;
    }
    :global(.ais-SearchBox-loadingIndicator) {
      display: none !important;
    }

    :global(.ais-SearchBox-input) {
      width: 100%;
      height: 100%;
      border-radius: 6px;
      background-color: var(--100);
      border: 1px solid var(--400);
      padding: 0 1rem 0 0.5rem;
      color: var(--700);
      &::-webkit-search-cancel-button {
        display: none;
      }
    }
    :global(.ais-SearchBox-submit) {
      display: none;
    }
  }
  // Refinement
  :global(.ais-RefinementList-label) {
    display: flex;
    align-items: center;
    padding: 5px;
    background-color: var(--200);
    cursor: pointer;
    border-radius: 5px;

    &:hover {
      background-color: var(--300);
    }
    .checkbox {
      margin-right: 0.5rem;
      accent-color: var(--accent);
    }
    .count {
      margin-left: auto;
      font-size: var(--step--1);
    }
  }
  :global(.ais-RefinementList) {
    display: flex;
    flex-direction: column;
    gap: 1rem;
    :global(.ais-RefinementList-list) {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 0.5rem;
    }
    :global(.ais-RefinementList-showMore) {
      width: fit-content;
      margin: auto;
    }
    :global(.ais-Highlight-highlighted) {
      background-color: var(--accent) !important;
    }
    :global(.ais-RefinementList-noResults) {
      font-size: var(--step--1);
    }
  }
}

