import Typesense from 'typesense';
import GuitarChordData from './data/guitar.json';
import 'dotenv/config';

(async () => {
  const typesense = new Typesense.Client({
    apiKey: [REDACTED] || 'xyz',
    nodes: [
      {
        host: process.env.NEXT_PUBLIC_TYPESENSE_HOST || 'localhost',
        port: parseInt(process.env.NEXT_PUBLIC_TYPESENSE_PORT || '8108'),
        protocol: process.env.NEXT_PUBLIC_TYPESENSE_PROTOCOL || 'http',
      },
    ],
  });

  try {
    await typesense.collections('guitar-chords').retrieve();
    console.log('Found existing collection of guitar-chords');

    console.log('Deleting collection');
    await typesense.collections('guitar-chords').delete();
  } catch (err) {
    console.error(err);
  }

  console.log('Creating schema...');

  await typesense.collections().create({
    name: 'guitar-chords',
    enable_nested_fields: true,
    fields: [
      {
        name: 'key',
        type: 'string',
        facet: true,
      },
      {
        name: 'suffix',
        type: 'string',
        facet: true,
      },
      {
        name: 'positions',
        type: 'object[]',
      },
      {
        name: 'positions.capo',
        type: 'bool[]',
        optional: true,
        facet: true,
      },
    ],
    symbols_to_index: ['#'],
  });

  console.log('Populating collection...');

  try {
    const returnData = await typesense
      .collections('guitar-chords')
      .documents()
      .import(GuitarChordData);

    console.log('Return data: ', returnData);
  } catch (err) {
    console.error(err);
  }
})();

export type _GuitarChord = {
  key: string;
  suffix: string;
  positions: (_chordPosition & {
    baseFret: number;
    midi: number[];
  })[];
};

export type _chordPosition = {
  frets: number[];
  fingers: number[];
  barres: number[];
  capo?: boolean;
};

'use client';
import s from './page.module.scss';
import { Configure, InfiniteHits, InstantSearch } from 'react-instantsearch';
import { typesenseInstantsearchAdapter } from '@/lib/typesense';
import { _GuitarChord } from '@/types/schema';
import HitItem from '@/components/HitItem/HitItem';
import SearchAndFilter from '@/components/SearchAndFilter/SearchAndFilter';
import Heading from '@/components/Heading/Heading';

export default function Home() {
  return (
    <main className={s.main}>
      <Heading />
      <div className={s.row}>
        <InstantSearch
          indexName='guitar-chords'
          searchClient={typesenseInstantsearchAdapter.searchClient}
          future={{ preserveSharedStateOnUnmount: true }}
        >
          <Configure hitsPerPage={12} />
          <SearchAndFilter />
          <InfiniteHits
            hitComponent={HitItem}
            showPrevious={false}
            classNames={{
              loadMore: s.loadMoreBtn,
            }}
          />
        </InstantSearch>
      </div>
    </main>
  );
}

